mapper.update:
update sms_flash_promotion_product_relation
set flash_promotion_count = flash_promotion_count - #{quantity}
where id = #{id} and flash_promotion_count - #{quantity} >= 0

update sms_flash_promotion_product_relation
set flash_promotion_count = flash_promotion_count + #{quantity}
where id = #{id}

mapper.select:
select ifnull(sum(r.quantity), 0)
from oms_order t
inner join oms_order_flash_relation r on t.id = r.order_id
where t.member_id = #{memberId}
  and r.flash_promotion_relation_id = #{relationId}
  and t.status != 4
